	/**
	 * Default Constructor
	 */
    public CandidateService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CandidateEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CandidateRepository.class) );
		this.validator		= applicationContext.getBean(CandidateValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Candidate
	 */
		public Candidate createCandidate( CreateCandidateCommand command ) {

		Candidate entity = new Candidate();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCandidateId( command.getCandidateId() );
            entity.setName( command.getName() );
            entity.setEmail( command.getEmail() );
            entity.setPhone( command.getPhone() );
            entity.setSource( command.getSource() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Candidate {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCandidateCommand
	 * @return		Candidate
	 */
	public Candidate updateCandidate( UpdateCandidateCommand command ) {

		Candidate entity = new Candidate();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCandidateId( command.getCandidateId() );
            entity.setName( command.getName() );
            entity.setEmail( command.getEmail() );
            entity.setPhone( command.getPhone() );
            entity.setApplications( command.getApplications() );
            entity.setInterviews( command.getInterviews() );
            entity.setOffers( command.getOffers() );
            entity.setDocuments( command.getDocuments() );
            entity.setSource( command.getSource() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Candidate {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCandidateCommand
	 */
	public void delete( DeleteCandidateCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCandidateId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Candidate {0} ", id );

	}

	/**
	 * Method to retrieve the Candidate via CandidateFetchOneSummary
	 * @param 	summary CandidateFetchOneSummary
	 * @return 	CandidateFetchOneResponse
	 */
	public Candidate getCandidate( CandidateFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CandidateFetchOneSummary arg cannot be null" );

		Candidate entity = null;
		UUID id = summary.getCandidateId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Candidate using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Candidates
	 *
	 * @return 	List<Candidate>
	 */
    public List<Candidate> getAllCandidate() {
		List<Candidate> list = projector.findAll( new FindAllCandidateQuery() );
		return list;
	}


	/**
	 * add JobApplication to Applications
	 * @param		command AssignApplicationsToCandidateCommand
	 */
	public void addToApplications( AssignApplicationsToCandidateCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToApplications(command.getCandidateId(), command.getAddTo());
	}

	/**
	 * remove JobApplication from Applications
	 * @param		command RemoveApplicationsFromCandidateCommand
	 */
	public void removeFromApplications( RemoveApplicationsFromCandidateCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromApplications(command.getCandidateId(), command.getRemoveFrom());
	}

